```javascript
// Install: npm install express-validator
const express = require('express');
const { 
  validationResult, 
  body, 
  param, 
  query,
  header 
} = require('express-validator');
const app = express();

// Middleware to handle validation results
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Validation chains for different endpoint types
const userIdValidation = [
  param('id')
    .trim()
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
];

const paginationValidation = [
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
];

const userDataValidation = [
  body('name')
    .trim()
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s\-']+$/)
    .withMessage('Name contains invalid characters'),

  body('email')
    .isEmail()
    .withMessage('Please provide a valid email address')
    .normalizeEmail(),

  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters long')
    .matches(/[a-z]/)
    .withMessage('Password must contain at least one lowercase letter')
    .matches(/[A-Z]/)
    .withMessage('Password must contain at least one uppercase letter')
    .matches(/[0-9]/)
    .withMessage('Password must contain at least one digit'),

  body('role')
    .optional()
    .isIn(['user', 'admin', 'moderator'])
    .withMessage('Role must be one of: user, admin, moderator')
];

// Apply validation to endpoints
app.get('/users/:id', 
  [...userIdValidation, ...paginationValidation],
  handleValidationErrors,
  (req, res) => {
    // All inputs are validated and safe to use
    res.json({ 
      userId: req.params.id,
      page: req.query.page || 1,
      limit: req.query.limit || 10
    });
  }
);

app.post('/users',
  [...userDataValidation],
  handleValidationErrors,
  (req, res) => {
    // Process validated user data
    res.status(201).json({ 
      message: 'User created successfully',
      userId: Date.now() // In production, use DB-generated ID
    });
  }
);

// Custom validator example
app.post('/custom-endpoint',
  body('customField')
    .custom((value) => {
      // Custom validation logic
      if (value.includes('<!')) {
        throw new Error('HTML not allowed in this field');
      }
      return true;
    }),
  handleValidationErrors,
  (req, res) => {
    res.json({ message: 'Custom field validated successfully' });
  }
);
